      &lt;span class="si"&gt;{&lt;/span&gt;&lt;span class="cm"&gt;/* The wrapper now forces horizontal scrolling only when needed */&lt;/span&gt;&lt;span class="si"&gt;}&lt;/span&gt;
      &lt;span class="si"&gt;{&lt;/span&gt;&lt;span class="nx"&gt;children&lt;/span&gt;&lt;span class="si"&gt;}&lt;/span&gt;
